/**
 * The project registry: `shared/projects.json`, generated by `npm run keys`.
 *
 * Addresses only — the matching private keys stay in gitignored `keys/`.
 * Safe to import from the browser.
 */
import registry from './projects.json' with { type: 'json' }
import type { Project } from './index.ts'

export const PROJECTS: readonly Project[] = registry as Project[]

export const PROJECT_IDS: readonly string[] = PROJECTS.map(p => p.id)

export function findProject(id: string): Project | undefined {
  return PROJECTS.find(p => p.id === id)
}

/** Address → project, for checking which project an output pays. */
export const PROJECTS_BY_ADDRESS: ReadonlyMap<string, Project> = new Map(
  PROJECTS.map(p => [p.address, p])
)
